mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}



        and reservation_time >= #{reservationBegin}


        and reservation_time < #{reservationEnd}


order by order_time desc

select  sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select count(id) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}

select od.name,sum(od.number) number from order_detail od,orders o where od.order_id=o.id and o.status=5
and o.order_time > #{begin}
and o.order_time < #{end}
group by od.name order by number desc limit 0,10

select round(sum(case when pay_status = 1 then amount else 0 end) * 100) as payTotal, round(sum(case when pay_status = 0 and status not in (6, 7) then amount else 0 end) * 100) as noPayTotal, count(distinct case when status not in (6, 7) then user_id end) as totalPerson from orders
and order_time >= #{begin}
and order_time <= #{end}
